SELECT CODE_ID, GROUP_CODE, CODE, CODE_NAME, PARENT_CODE_ID, SORT_ORDER, USE_YN FROM T_CODE
AND GROUP_CODE = #{group_code}
AND PARENT_CODE_ID = #{parent_code_id}
AND USE_YN = #{use_yn}
AND (CODE LIKE '%' || #{keyword} || '%' OR CODE_NAME LIKE '%' || #{keyword} || '%')
ORDER BY SORT_ORDER ASC

SELECT ST.SHOWTIME_ID, M.TITLE AS MOVIE_TITLE, T.THEATER_NAME, SC.NAME AS SCREEN_NAME, TO_CHAR(ST.START_AT, 'YYYY-MM-DD HH24:MI') AS START_AT, TO_CHAR(ST.END_AT, 'YYYY-MM-DD HH24:MI') AS END_AT, ST.SEAT_COUNT, COUNT(SS.BOOKER_USER_UID) AS BOOKED_SEAT_COUNT FROM T_MOVIE_SHOWTIME ST JOIN MOVIE M ON M.MOVIE_ID = ST.MOVIE_ID JOIN T_THEATER T ON T.THEATER_ID = ST.THEATER_ID JOIN T_SCREEN SC ON SC.SCREEN_ID = ST.SCREEN_ID LEFT JOIN T_MOVIE_SHOWTIME_SEAT SS ON SS.SHOWTIME_ID = ST.SHOWTIME_ID
AND ST.THEATER_ID = #{theaterId}
AND ST.MOVIE_ID = #{movieId}
AND TO_CHAR(ST.START_AT, 'YYYY-MM-DD') = #{showDate}
GROUP BY ST.SHOWTIME_ID, M.TITLE, T.THEATER_NAME, SC.NAME, ST.START_AT, ST.END_AT, ST.SEAT_COUNT ORDER BY ST.START_AT ASC

SELECT SCREEN_ID, NAME, CAPACITY, GRID_COLUMNS, GRID_ROWS
FROM T_SCREEN
WHERE SCREEN_ID = #{screenId}

mapper.update:
UPDATE T_MOVIE_SHOWTIME_SEAT
SET BOOKER_USER_UID = (SELECT USER_UID FROM USERS WHERE LOGIN_ID = TO_CHAR(#{userId}) OR TO_CHAR(USER_UID) = TO_CHAR(#{userId})),
BOOKING_ID = #{bookingId}
WHERE SHOWTIME_ID = #{showtimeId}
AND SEAT_NO IN

    #{seatNo}

AND BOOKER_USER_UID IS NULL
